@pytest.mark.anyio async def test_serum_cream_question_keeps_order_and_context(monkeypatch, connections): monkeypatch.setattr(get_settings(), "g8_enabled", True) api, skincare, catalog = connections consult = install_knowledge(monkeypatch) question = "건조할 때 아침에 세럼과 크림은 어떤 순서와 방법으로 사용하나요?"
class OrderPlanner(Planner): async def complete_with_tools(self, messages, tools, *, required_tool=None): reply, ms = await super().complete_with_tools( messages, tools, required_tool=required_tool ) if required_tool == "plan_skin_consultation": call = reply["choices"][0]["message"]["tool_calls"][0]["function"] plan = json.loads(call["arguments"]) plan["question"] = question call["arguments"] = json.dumps(plan) return reply, ms
chat = ChatService(None, OrderPlanner(), catalog, skincare=skincare) await chat.answer(ChatRequest(message=question + " 제품도 추천해 줘.", locale="ko")) > consult.assert_awaited_once_with(question)
